  const remember=()=>{try{localStorage.setItem(key,JSON.stringify(prefs));}catch{host.toast('Не удалось сохранить настройки браузера.');}};
  function apply(){panel.querySelector('[role=separator]')?.setAttribute('aria-valuenow',String(prefs.width));document.documentElement.dataset.density=prefs.density;document.documentElement.classList.toggle('nav-collapsed',prefs.collapsed);document.documentElement.classList.toggle('preview-open',!!selected);document.documentElement.style.setProperty('--preview-width',prefs.width+'px');}
  function title(kind     ,id       ){return kind==='file'?host.diskFiles().find(f=>f.id===id)?.name:(kind==='note'?host.data().notes:host.data().tasks).find(n=>n.id===id)?.title;}
