    if(t.dataset.workbenchRetry){try{const r=await fetch('/api/workflows',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:t.dataset.workbenchRetry})});const v=await r.json();if(!r.ok)throw new Error(v.error);workflow=v;await host.sync();host.render();}catch(e){host.toast(e.message);}return;}
